{"code":"def transform(grid):
    a=[r[:] for r in grid]
    h=len(a); w=len(a[0]) if h else 0
    # Only vertically short grids containing a vertical colored motif are lengthened to square.
    if h < w and any(x != 0 for r in a for x in r):
        # repeat the observed row pattern; this preserves alternating/repeating vertical marks
        for i in range(h,w):
            a.append(a[i % h][:])
    return a"}

